INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.hp-scale', 'real', '0.5', 'Multiplies every boss health pool.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.damage-scale', 'real', '0.6', 'Multiplies every hit bosses deal to players.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.incoming-damage-scale', 'real', '1.0', 'Multiplies every hit players deal to bosses (calibrate to the items damage formula).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.target-seconds', 'real', '240', 'A boss of the tier is built to die in this many seconds to one player with the tier''s sword and armor (hit the weakness).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.slayer.target-seconds', 'real', '90', 'Same for a slayer boss of the tier, against a target with no weakness.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.tick-period', 'int', '2', 'Ticks between two boss updates (1-10).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.bar-range', 'int', '64', 'Players closer than this see the boss bar.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.visual-health', 'int', '300', 'Max health attribute of the entity (only mirrors the percentage).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.hit-iframes', 'int', '6', 'Invulnerability ticks of a boss between two hits.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.magic-find-cap', 'int', '1000', 'Fortune above this is ignored.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.purge-orphans', 'bool', 'true', 'Remove tagged boss entities left behind (bosses never persist across a restart).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.scale-min-share', 'real', '0.01', 'A player grows the boss health pool only after dealing this fraction of its base health.');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.repeat-window-minutes', 'int', '60', 'Kills of the same boss inside this window lower the next payout (coins and combat xp)...');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.repeat-decay', 'real', '0.2', '...by this fraction per earlier kill...');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.repeat-floor', 'real', '0.25', '...down to this fraction (0 decay turns the damper off).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.settings.damage-numbers', 'bool', 'true', 'Floating damage numbers on bosses (they take a token real hit, so the generic ones read 0).');
INSERT INTO setting (id, type, value, note) VALUES ('boss.slayer.enabled', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.slayer.ignore-spawner-mobs', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.slayer.spawn-min-distance', 'int', '6', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.slayer.spawn-max-distance', 'int', '10', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.slayer.spawn-countdown-seconds', 'int', '3', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.world.enabled', 'bool', 'false', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.world.interval-minutes', 'int', '120', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.world.first-spawn-delay-minutes', 'int', '30', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.world.min-players', 'int', '1', '');
INSERT INTO setting (id, type, value, note) VALUES ('boss.world.announce-before-seconds', 'list', '', 'Warnings before the spawn, seconds.');
